# v137: Lernen – „Heute üben“ (10-Minuten-Plan, „▶ Los“ mit Timer, Serie), „Weiter, wo du warst“, Hör-Training (Intervalle/Akkorde/
# Tonleitern, Ampel, gespeichert), Spickzettel (druckfreundlich), Lazy, keine Sprünge, keine Skriptfehler
import asyncio, sys, re, datetime
from playwright.async_api import async_playwright
from nav import tab
U = 'http://localhost:8765/index.html'
ok = 0; tot = 0
def check(n, c, info=''):
    global ok, tot; tot += 1; ok += bool(c); print(('OK    ' if c else 'FEHLER') + '  ' + n + ('  · ' + str(info) if info != '' else ''), flush=True)
Y = (datetime.date.today() - datetime.timedelta(days=1)).isoformat()
TD = datetime.date.today().isoformat()
SPY = "window.__pn=[];const o=Quinten.playNote;Quinten.playNote=m=>{__pn.push([m,performance.now()]);o(m)};0"
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(args=['--autoplay-policy=no-user-gesture-required'])
        ctx = await b.new_context(viewport={'width': 1180, 'height': 820}); pg = await ctx.new_page(); errs = []
        pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.add_init_script("if(!sessionStorage.getItem('x')){sessionStorage.setItem('x',1);localStorage.setItem('3nps-lernen', JSON.stringify({serie:3,last:'%s'}))}" % Y)
        await pg.goto(U); await pg.wait_for_timeout(900)
        check('v137', 'v137' in await pg.inner_text('.brand'))
        lz = await pg.evaluate("[document.getElementById('hrBody').children.length, document.getElementById('spBody').children.length, document.getElementById('lnTiles').children.length]")
        check('Lazy: Hör-Training, Spickzettel, Übersicht beim Start leer', lz == [0, 0, 0], lz)
        await tab(pg, 'lernen'); await pg.wait_for_timeout(300)
        chips = await pg.evaluate("[...document.querySelectorAll('#subNav [data-area=lernen]')].map(c=>c.dataset.tab)")
        check('Lernen-Chips mit Hör-Training und Spickzettel', chips == ['lernen', 'power', 'caged', 'quinten', 'griffbrett', 'ueben', 'hoer', 'spick'], chips)
        tiles = await pg.evaluate("[...document.querySelectorAll('.ln-tile')].map(t=>t.dataset.t)")
        check('Kacheln Hör-Training und Spickzettel', 'hoer' in tiles and 'spick' in tiles and len(tiles) == 7, tiles)
        t = await pg.inner_text('#lnToday')
        check('Heute üben: 10-Minuten-Plan', 'Heute üben · 10 Min' in t and '3 Min Technik' in t and '4 Min Kurs Kap. 1' in t and '3 Min Hör-Training' in t, t)
        check('Serie von gestern sichtbar (3 Tage)', 'Serie: 3 Tage' in t, t)
        # ▶ Los → Schritt 1 Technik, feste Leiste, Timer läuft
        top0 = await pg.evaluate("Math.round(document.getElementById('subNav').getBoundingClientRect().top + scrollY)")
        await pg.click('#lnGo'); await pg.wait_for_timeout(400)
        r = await pg.evaluate("({run:Lernen.run(),cur:AppNav.current(),pos:getComputedStyle(document.getElementById('lnRun')).position,txt:document.getElementById('lnRun').textContent})")
        check('▶ Los: Schritt 1/3 Technik, Leiste fest unten, 3:00', r['run']['i'] == 0 and r['cur'] == 'griffbrett' and r['pos'] == 'fixed' and '1/3' in r['txt'] and ('3:00' in r['txt'] or '2:59' in r['txt']), r)
        await pg.wait_for_timeout(2300)
        l1 = await pg.evaluate("Lernen.run().left")
        check('Timer zählt herunter', 176 <= l1 <= 178, l1)
        await pg.click('#lnRun [data-run=pause]'); await pg.wait_for_timeout(1500); l2 = await pg.evaluate("Lernen.run().left")
        check('⏸ hält den Timer an', l2 == l1 or l2 == l1 - 1, (l1, l2))
        await pg.click('#lnRun [data-run=pause]')
        top1 = await pg.evaluate("Math.round(document.getElementById('subNav').getBoundingClientRect().top + scrollY)")
        check('Leiste verschiebt nichts', top0 == top1, (top0, top1))
        await pg.evaluate(SPY)
        await pg.evaluate("Lernen._shift(200)"); await pg.wait_for_timeout(700)
        r = await pg.evaluate("({run:Lernen.run(),cur:AppNav.current(),sec:Powerchords.ui().sec,open:!!(document.getElementById('pcKC1')||{}).open,beep:__pn.length})")
        check('Zeit um → Ton + Schritt 2: Kurs Kap. 1 geöffnet', r['run']['i'] == 1 and r['cur'] == 'power' and r['sec'] == 'kurs' and r['open'] and r['beep'] >= 1, r)
        await pg.click('#lnRun [data-run=next]'); await pg.wait_for_timeout(400)
        r = await pg.evaluate("({run:Lernen.run(),cur:AppNav.current()})")
        check('„Weiter ▸“ → Schritt 3: Hör-Training', r['run']['i'] == 2 and r['cur'] == 'hoer', r)
        await pg.click('#lnRun [data-run=next]'); await pg.wait_for_timeout(400)
        r = await pg.evaluate("({txt:document.getElementById('lnRun').textContent,L:Lernen._L()})")
        check('Fertig → „Geschafft!“, Serie 4 Tage gespeichert', 'Geschafft' in r['txt'] and 'Serie: 4 Tage' in r['txt'] and r['L']['serie'] == 4 and r['L']['last'] == TD, r)
        await pg.wait_for_timeout(5300)
        check('Leiste verschwindet danach', await pg.evaluate("!document.getElementById('lnRun') && !Lernen.run()"))
        await tab(pg, 'lernen'); await pg.wait_for_timeout(200); t = await pg.inner_text('#lnToday')
        check('Übersicht: Serie 4 Tage ✓ (heute geschafft)', 'Serie: 4 Tage ✓' in t, t)
        await pg.click('#lnGo'); await pg.wait_for_timeout(300); await pg.click('#lnRun [data-run=stop]'); await pg.wait_for_timeout(200)
        check('✕ bricht ab, Serie bleibt', await pg.evaluate("!Lernen.run() && !document.getElementById('lnRun') && Lernen.serie()===4"))
        # Weiter, wo du warst
        await tab(pg, 'power'); await pg.wait_for_timeout(300)
        await pg.evaluate("Powerchords.showSec('kurs'); PcKurs.open(6); 0"); await pg.wait_for_timeout(500)
        await pg.click('#pcKC6 .pc-kstep[data-s="1"]'); await pg.wait_for_timeout(300)
        w = await pg.evaluate("Lernen.where()")
        check('Stelle gemerkt: Kurs Kap. 6 Schritt 2', w == {'t': 'power', 'sec': 'kurs', 'k': 6, 's': 1}, w)
        await pg.evaluate("document.getElementById('pcKC6').open=false; document.getElementById('pcKC1').open=false; Powerchords.showSec('theorie'); 0")
        # Theorie-Klick über Unterleiste würde die Stelle überschreiben – hier nur programmatisch
        await tab(pg, 'looper'); await pg.reload(); await pg.wait_for_timeout(900)
        await tab(pg, 'lernen'); await pg.wait_for_timeout(300)
        t = await pg.inner_text('#lnToday'); lt = await pg.evaluate("(document.querySelector('.ln-tile.last')||{}).textContent||''")
        check('„↩ Weiter: Powerchords-Kurs · Kap. 6 · Schritt 2“ nach Neustart', 'Weiter: Powerchords-Kurs · Kap. 6 · Schritt 2' in t, t)
        check('Kachel zeigt „Zuletzt: Kap. 6 …“', 'Zuletzt: Kap. 6' in lt, lt)
        check('Plan nimmt das aktuelle Kapitel (Kap. 6)', '4 Min Kurs Kap. 6' in t, t)
        await pg.click('#lnResume'); await pg.wait_for_timeout(1200)
        r = await pg.evaluate("(()=>{const S0=PcKurs.K[5].s[1],el=document.getElementById('pcK_'+S0.id);return {cur:AppNav.current(),sec:Powerchords.ui().sec,open:document.getElementById('pcKC6').open,top:el&&Math.round(el.getBoundingClientRect().top)}})()")
        check('Weiter öffnet genau Kap. 6, Schritt 2', r['cur'] == 'power' and r['sec'] == 'kurs' and r['open'] and r['top'] is not None and -10 < r['top'] < 300, r)
        await tab(pg, 'ueben'); await pg.click('#ubNav [data-s=ohr]'); await pg.wait_for_timeout(200)
        check('Training-Bereich gemerkt (Gehörbildung)', await pg.evaluate("Lernen.where()") == {'t': 'ueben', 'ub': 'ohr'})
        await pg.evaluate("Ueben.showSec('tag'); 0"); await tab(pg, 'looper')
        await tab(pg, 'lernen'); await pg.click('#lnResume'); await pg.wait_for_timeout(400)
        check('Weiter → Training · Gehörbildung', await pg.evaluate("AppNav.current()==='ueben' && !document.querySelector('#panel-ueben .ub-sec[data-s=ohr]').hidden && document.querySelector('#ubNav [data-s=ohr]').classList.contains('active')"))
        # Hör-Training
        await tab(pg, 'hoer'); await pg.wait_for_timeout(300)
        await pg.evaluate(SPY)
        await pg.click('[data-hm=iv]'); await pg.click('[data-hd=up]'); y0 = await pg.evaluate("Math.round(document.getElementById('hrBody').getBoundingClientRect().top)")
        n = await pg.evaluate("document.querySelectorAll('.hr-a').length")
        check('Intervalle: Ampel mit 12 Intervallen', n == 12, n)
        await pg.click('[data-hr=start]'); await pg.wait_for_timeout(1100)
        q = await pg.evaluate("Hoer.task()"); pn = await pg.evaluate("__pn")
        check('aufwärts: zwei Töne nacheinander, zweiter höher', len(pn) == 2 and pn[1][0] - pn[0][0] == int(q['k']) and pn[1][1] - pn[0][1] > 500, (q, pn))
        await pg.click('[data-ha="%s"]' % q['k']); await pg.wait_for_timeout(100)
        fb = await pg.inner_text('.hr-fb')
        check('Richtige Antwort: „✓ Richtig!“, Treffer 1', fb.startswith('✓ Richtig!') and 'Treffer: 1' in await pg.inner_text('#hrBody'), fb)
        await pg.click('[data-hr=next]'); await pg.wait_for_timeout(200)
        q = await pg.evaluate("Hoer.task()"); wrong = '1' if q['k'] != '1' else '2'
        await pg.click('[data-ha="%s"]' % wrong); fb = await pg.inner_text('.hr-fb')
        check('Falsche Antwort: „✗ Das war …“, richtige markiert', fb.startswith('✗ Das war') and await pg.evaluate("document.querySelector('[data-ha=\"%s\"]').classList.contains('active')" % q['k']), fb)
        await pg.click('[data-hd=down]'); await pg.evaluate("__pn.length=0"); await pg.click('[data-hr=next]'); await pg.wait_for_timeout(1100)
        q = await pg.evaluate("Hoer.task()"); pn = await pg.evaluate("__pn")
        check('abwärts: erst hoch, dann tief', len(pn) == 2 and pn[0][0] - pn[1][0] == int(q['k']), (q, pn))
        await pg.click('[data-hd=both]'); await pg.evaluate("__pn.length=0"); await pg.click('[data-hr=again]'); await pg.wait_for_timeout(400)
        pn = await pg.evaluate("__pn")
        check('zusammen: beide Töne gleichzeitig', len(pn) == 2 and abs(pn[1][1] - pn[0][1]) < 50, pn)
        for i in range(8):
            q = await pg.evaluate("Hoer.task()"); await pg.evaluate("Hoer.answer('%s')" % q['k'])
            if i < 7: await pg.click('[data-hr=next]')
        await pg.wait_for_timeout(100)
        st = await pg.evaluate("Hoer.stats()")
        check('Runde fertig: „Neue Runde“, beste Runde 9/10 gespeichert', 'Neue Runde' in await pg.inner_text('#hrBody') and st['best'].get('iv') == 9 and 'Beste Runde: 9/10' in await pg.inner_text('#hrBody'), st['best'])
        await pg.click('[data-hm=ch]'); await pg.wait_for_timeout(100)
        y1 = await pg.evaluate("Math.round(document.getElementById('hrBody').getBoundingClientRect().top)")
        opts = await pg.evaluate("document.querySelectorAll('.hr-a').length")
        check('Akkorde: Typen aus dem Kurs-Hör-Training (8), Richtungsleiste ohne Sprung', opts == 8 and y0 == y1 and await pg.evaluate("getComputedStyle(document.getElementById('hrDir')).visibility") == 'hidden', (opts, y0, y1))
        await pg.evaluate("__pn.length=0"); await pg.click('[data-hr=start]'); await pg.wait_for_timeout(700)
        check('Akkord: mehrere Töne fast gleichzeitig', await pg.evaluate("__pn.length>=3 && __pn[__pn.length-1][1]-__pn[0][1]<300"), await pg.evaluate("__pn.length"))
        await pg.click('[data-hm=sc]'); await pg.evaluate("__pn.length=0"); await pg.click('[data-hr=start]'); await pg.wait_for_timeout(3200)
        q = await pg.evaluate("Hoer.task()"); n = await pg.evaluate("__pn.length")
        names = await pg.evaluate("[...document.querySelectorAll('[data-ha]')].map(b=>b.textContent)")
        check('Tonleitern: Dur, Moll, Pentatoniken, Kirchentonarten; Leiter wird gespielt', all(x in names for x in ['Dur', 'Moll', 'Dur-Pentatonik', 'Moll-Pentatonik', 'Dorisch', 'Phrygisch', 'Lydisch', 'Mixolydisch', 'Lokrisch']) and n in (6, 8), (names, n))
        await pg.evaluate("Hoer.answer('%s')" % q['k'])
        await pg.reload(); await pg.wait_for_timeout(900); await tab(pg, 'hoer'); await pg.wait_for_timeout(200)
        st = await pg.evaluate("Hoer.stats()")
        check('Nach Neustart: Treffer + Modus gespeichert', st['mode'] == 'sc' and sum(v[1] for v in st['iv'].values()) == 10 and sum(v[0] for v in st['iv'].values()) == 9 and sum(v[1] for v in st['sc'].values()) == 1, st)
        await pg.evaluate("(()=>{const s=JSON.parse(localStorage.getItem('3nps-hoer'));s.iv['7']=[4,4];s.iv['3']=[1,4];localStorage.setItem('3nps-hoer',JSON.stringify(s))})()")
        await pg.reload(); await pg.wait_for_timeout(900); await tab(pg, 'hoer'); await pg.click('[data-hm=iv]')
        amp = await pg.evaluate("[...document.querySelectorAll('.hr-a')].map(a=>a.className.split(' ')[1])")
        check('Ampel: Quinte grün, kleine Terz rot', amp[6] == 'gruen' and amp[2] == 'rot', amp)
        await tab(pg, 'lernen'); await pg.wait_for_timeout(200)
        hp = await pg.evaluate("document.querySelector('.ln-tile[data-t=hoer] .ln-p').textContent")
        check('Kachel Hör-Training zeigt Trefferquote', '%' in hp and 'Treffer' in hp, hp)
        # Spickzettel
        await tab(pg, 'spick'); await pg.wait_for_timeout(300)
        sp = await pg.evaluate("({s:[...document.querySelectorAll('#spBody h3')].map(h=>h.textContent),t:document.querySelectorAll('#spBody table').length,iv:document.querySelectorAll('#spBody table')[0].tBodies[0].rows.length,txt:document.getElementById('spBody').textContent})")
        check('Spickzettel: Intervalle, Griffformen, Quintenzirkel, Akkordsymbole', all(x in sp['s'] for x in ['Intervalle', 'Powerchord-Formen', 'Quintenzirkel', 'Akkordsymbole']) and sp['t'] == 5 and sp['iv'] == 13, sp['s'])
        check('Spickzettel: Inhalte stimmen (Beispiele)', all(x in sp['txt'] for x in ['Tritonus', 'x32010', '022100', 'Cmaj7', '1 3 5 7', '1 b3 b5 b7', 'F#m', '3♯']), '')
        await pg.evaluate("document.documentElement.classList.add('print-spick')"); await pg.emulate_media(media='print')
        pv = await pg.evaluate("({tabs:getComputedStyle(document.querySelector('.tabs')).visibility,hdr:getComputedStyle(document.querySelector('header')).visibility,sp:getComputedStyle(document.querySelector('#spBody td')).visibility,col:getComputedStyle(document.querySelector('#spBody td')).color,btn:getComputedStyle(document.getElementById('spPrint')).display})")
        check('Druck: nur Spickzettel, schwarz, ohne Knopf', pv['tabs'] == 'hidden' and pv['hdr'] == 'hidden' and pv['sp'] == 'visible' and pv['col'] == 'rgb(0, 0, 0)' and pv['btn'] == 'none', pv)
        await pg.emulate_media(media='screen'); await pg.evaluate("document.documentElement.classList.remove('print-spick')")
        await pg.set_viewport_size({'width': 768, 'height': 1024}); await pg.wait_for_timeout(200)
        check('Hochkant: nichts ragt heraus', await pg.evaluate("document.documentElement.scrollWidth<=innerWidth+1"))
        # „?“ aus den neuen Unterpunkten
        for t, want in [('hoer', 'hoer-training'), ('spick', 'spickzettel')]:
            await tab(pg, t); await pg.click('#tab-hilfe'); await pg.wait_for_timeout(900)
            on = await pg.evaluate("(document.querySelector('#hlToc a.on')||{dataset:{}}).dataset.id")
            check('„?“ aus %s → %s' % (t, want), on == want, on); await pg.click('#tab-hilfe')
        check('keine Skriptfehler', not errs, errs[:3])
        await b.close()
    print('\n%d/%d' % (ok, tot)); sys.exit(0 if ok == tot else 1)
asyncio.run(main())
